conn = sqlite3.connect(DB_PATH)
c = conn.cursor()

inserted = 0
for topic, diff, qtext, oa, ob, oc, od, ans, exp in oop_questions + oop_hard_questions:
    c.execute("SELECT id FROM assessment_questions WHERE assessment_type='technical' AND question_text=?", (qtext,))
    if c.fetchone() is None:
        c.execute("""
            INSERT INTO assessment_questions (id, assessment_type, topic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, is_active)
            VALUES (?, 'technical', ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
        """, (str(uuid.uuid4()), topic, diff, qtext, oa, ob, oc, od, ans, exp))
        inserted += 1

conn.commit()
conn.close()
print(f"Inserted {inserted} OOP questions for Technical.")
